const activeRoute=page=>ui.page===page||(page==='library'&&['deck','study','test','match','arcade','stroke','stats'].includes(ui.page));
function nav(page,deckId){clearInterval(timerHandle);timerHandle=null;ui.page=page;if(deckId)ui.deckId=deckId;ui.modal='';ui.session=null;ui.match=null;ui.test=null;document.body.classList.remove('mobile-nav');render();window.scrollTo(0,0)}
function render(){document.documentElement.dataset.theme=data.settings.theme;document.documentElement.dataset.bigtext=data.settings.largeText?'yes':'no';document.documentElement.dataset.calm=data.settings.calmMotion?'yes':'no';document.body.classList.toggle('study-focus',!!data.settings.focusMode&&['study','stroke'].includes(ui.page));const pageTitle={home:'Dashboard',library:'My library',deck:'Your study set',study:'Study session',match:'Match game',arcade:'Study games',stroke:'Chinese handwriting',test:'Practice test',import:'Import cards',settings:'Preferences',stats:'Your progress'};$('#app').innerHTML=`<div class="shell"><div class="mobile-backdrop" data-act="close-menu"></div><aside class="sidebar"><div class="brand"><span class="brand-logo">${icon('brain')}</span> Recall <span style="color:var(--brand)">Studio</span></div><div class="nav-label">WORKSPACE</div>${navItem('home','home','Dashboard')}${navItem('library','library','My library')}${navItem('stats','chart','Study analytics')}<div class="nav-label" style="margin-top:24px">TOOLS</div>${navItem('import','upload','Import cards')}${navItem('settings','settings','Settings')}<div class="sidebar-spacer"></div><div class="offline-note"><div style="font-size:12px;font-weight:800;margin-bottom:4px"><span class="online-dot"></span> Offline-ready</div><div class="small muted">No sign-in. No ads. Your decks stay on this device. Back up to move them.</div></div><div class="small muted" style="padding:15px 12px 0">Independent & free • v5.0</div></aside><main class="main"><header class="topbar"><div class="top-left"><button class="icon-btn menu-toggle" data-act="open-menu" aria-label="Open navigation">${icon('menu')}</button><span class="top-title">${pageTitle[ui.page]||'Recall Studio'}</span></div><div class="top-actions"><button class="icon-btn" data-act="show-help" title="Keyboard shortcuts (?)" aria-label="Keyboard shortcuts">?</button><span class="pill purple" style="display:flex;align-items:center;gap:6px">${icon('cloudOff')} <span class="btn-text">Private & offline</span></span><button class="btn small primary" data-act="new-deck">${icon('plus')} <span class="btn-text">New set</span></button></div></header><div class="content">${backupReminder()}${renderPage()}</div></main></div>`;renderModal();}
function navItem(page,ico,label){return `<button class="navbtn ${activeRoute(page)?'active':''}" data-act="nav" data-page="${page}">${icon(ico)} ${esc(label)}</button>`}
function renderPage(){switch(ui.page){case'home':return homePage();case'library':return libraryPage();case'deck':return deckPage();case'study':return studyPage();case'match':return matchPage();case'arcade':return arcadePage();case'stroke':return strokePage();case'test':return testPage();case'import':return importPage();case'settings':return settingsPage();case'stats':return statsPage();default:return homePage()}}
function statBlock(name,value,ico){return `<div class="stat"><div class="stat-top"><span class="muted">${name}</span><span class="stat-icon">${icon(ico)}</span></div><strong>${value}</strong></div>`}
function homePage(){let total=allCards(),studied=data.decks.flatMap(d=>d.cards).filter(c=>c.correct+c.wrong>0).length,deck=data.decks[0];return `<div class="welcome"><div><div class="eyebrow" style="color:#ddd9ff">YOUR LEARNING SPACE</div><h1>Small steps. Big memory.</h1><p>Everything you need to learn, practice and remember — without a paywall or an internet connection.</p><button class="btn" data-act="${deck?'open-deck':'new-deck'}" data-id="${deck?.id||''}">${icon('zap')} ${deck?'Continue studying':'Create your first deck'}</button></div><div class="welcome-art" aria-hidden="true">🧠</div></div><div class="stats-grid">${statBlock('Study sets',data.decks.length,'library')}${statBlock('Total cards',total,'cards')}${statBlock('Cards practised',studied,'check')}${statBlock('Due for review',totalDue(),'clock')}</div><div class="heading-row"><div><h2>My study sets</h2><div class="muted small">Pick up right where you left off</div></div><button class="btn small" data-act="nav" data-page="library">View all ${icon('arrow')}</button></div>${data.decks.length?`<div class="cards-grid">${data.decks.slice(0,8).map(deckCard).join('')}</div>`:emptyDeck()}${data.history.length?`<div class="heading-row"><div><h2>Recent learning</h2><div class="muted small">Your latest practice results</div></div></div><div class="surface">${historyHtml(4)}</div>`:''}`}
function deckCard(d){let p=deckMastery(d);return `<article class="deck-card" data-act="open-deck" data-id="${escAttr(d.id)}" tabindex="0" role="button" aria-label="Open ${escAttr(d.title)}"><div class="row space-between"><span class="deck-icon">📚</span><span class="pill">${esc(d.subject||'General')}</span></div><div class="grow"><h3>${esc(d.title)}</h3><div class="deck-meta">${icon('cards')} ${d.cards.length} terms ${d.folder?`· ${esc(d.folder)}`:''}</div></div><div class="row space-between small"><span class="muted">Mastery</span><strong>${p}%</strong></div><div class="bar"><span style="width:${p}%"></span></div></article>`}
function emptyDeck(){return `<div class="empty surface"><div class="empty-art">📚</div><h3>No study sets yet</h3><p class="muted">Create a set or import your existing flashcards.</p><button class="btn primary" data-act="new-deck">${icon('plus')} Create a set</button> <button class="btn" data-act="nav" data-page="import">Import cards</button></div>`}
function libraryPage(){
 const lf=ui.libraryFilters;
 const folders=[...new Set(data.decks.map(d=>d.folder).filter(Boolean))].sort((a,b)=>a.localeCompare(b));
 const subjects=[...new Set(data.decks.map(d=>d.subject||'General'))].sort((a,b)=>a.localeCompare(b));
 const query=ui.q.trim().toLocaleLowerCase();
 const statusOk=(d)=>{
  const m=setMetrics(d);
  switch(lf.status){
   case 'new':return m.unseen===d.cards.length;
   case 'learning':return m.learning>0;
   case 'mastered':return d.cards.length>0&&m.mastered===d.cards.length;
   case 'starred':return m.starred>0;
   case 'due':return d.cards.some(due);
   default:return true;
  }
 };
 const list=data.decks.filter(d=>(ui.filter==='all'||d.folder===ui.filter)&&(lf.subject==='all'||(d.subject||'General')===lf.subject)&&statusOk(d)&&(!query||[d.title,d.description,d.subject,d.folder].some(x=>String(x||'').toLocaleLowerCase().includes(query))||d.cards.some(c=>`${c.term} ${c.definition} ${c.pinyin||''}`.toLocaleLowerCase().includes(query))));
 const sorts={recent:(a,b)=>(b.created||0)-(a.created||0),name:(a,b)=>a.title.localeCompare(b.title),cards:(a,b)=>b.cards.length-a.cards.length,review:(a,b)=>b.cards.filter(due).length-a.cards.filter(due).length,mastery:(a,b)=>deckMastery(a)-deckMastery(b)};
 list.sort(sorts[lf.sort]||sorts.recent);
 const selectedCount=lf.selected.filter(id=>data.decks.some(d=>d.id===id)).length;
 const activeFilters=(ui.filter!=='all')+(lf.subject!=='all')+(lf.status!=='all')+(!!query);
 const optionList=(values,chosen)=>values.map(([val,label])=>`<option value="${escAttr(val)}" ${chosen===val?'selected':''}>${esc(label)}</option>`).join('');
 const hasLegacyChinese=data.decks.some(d=>d.cards.some(c=>/你们|nǐmen|nimen/i.test(String(c.term||'')+' '+String(c.pinyin||''))));
 return `<div class="heading-row"><div><div class="eyebrow">COLLECTION</div><h1>My library</h1><p class="muted">Your saved sets. Search, filter, or remove anything you no longer need.</p></div><div class="row wrap"><button class="btn" data-act="nav" data-page="import">${icon('upload')} Import</button><button class="btn primary" data-act="new-deck">${icon('plus')} Create set</button></div></div>
 ${hasLegacyChinese?`<div class="legacy-explainer"><span aria-hidden="true">ℹ</span><span>Seeing <strong>nǐmen / 你们</strong>? An older Mandarin set is still saved in your library. It wasn't re-added by this version. Use the trash icon on that set to remove it if you don't need it.</span></div>`:''}
 <div class="surface library-filters" aria-label="Library search and filters">
  <div class="row wrap space-between filter-heading"><strong>Find study sets</strong><div class="row wrap gap-sm"><span class="muted small">${list.length} of ${data.decks.length} sets</span><button class="btn small" data-act="reset-library-filters" ${activeFilters?'':'disabled'}>Clear filters ${activeFilters?'('+activeFilters+')':''}</button><button class="btn small ${lf.selectMode?'soft':''}" data-act="toggle-bulk-select">${lf.selectMode?'Done selecting':'Select multiple'}</button></div></div>
  <div class="search library-search">${icon('search')}<input data-role="library-search" placeholder="Search set names or words…" value="${escAttr(ui.q)}" aria-label="Search sets"/></div>
  <div class="filter-row folder-filters"><button class="filter ${ui.filter==='all'?'active':''}" data-act="folder-filter" data-folder="all">All folders</button>${folders.map(f=>`<button class="filter ${ui.filter===f?'active':''}" data-act="folder-filter" data-folder="${escAttr(f)}">${esc(f)}</button>`).join('')}</div>
  <div class="library-filter-grid">
   <label>Subject<select class="select" data-library-filter="subject" aria-label="Filter library by subject">${optionList([['all','Any subject'],...subjects.map(x=>[x,x])],lf.subject)}</select></label>
   <label>Progress<select class="select" data-library-filter="status" aria-label="Filter library by study progress">${optionList([['all','Any progress'],['new','Not studied'],['learning','Still learning'],['mastered','All mastered'],['starred','Contains starred cards'],['due','Due for review']],lf.status)}</select></label>
   <label>Sort by<select class="select" data-library-filter="sort" aria-label="Sort library">${optionList([['recent','Newest first'],['name','Name A–Z'],['cards','Most cards'],['review','Most due'],['mastery','Least mastered']],lf.sort)}</select></label>
  </div>
  ${lf.selectMode?`<div class="bulk-actions"><span>${selectedCount} selected</span><button class="btn small" data-act="select-filtered-decks">Select shown</button><button class="btn small" data-act="unselect-decks">Clear selection</button><button class="btn small danger" data-act="delete-selected-decks" ${selectedCount?'':'disabled'}>${icon('trash')} Delete selected</button></div>`:''}
 </div>
 ${list.length?`<div class="cards-grid">${list.map(deckCard).join('')}</div>`:`<div class="surface empty"><h3>No matching sets</h3><p class="muted">Try clearing a filter or searching a different term.</p><button class="btn" data-act="reset-library-filters">Clear filters</button></div>`}`;
}

function modeButton(id,ico,title,desc){return `<button class="mode-card" data-act="start" data-mode="${id}"><span class="mode-icon">${icon(ico)}</span><span><strong>${title}</strong><small>${desc}</small></span></button>`}
function deckPage(){let d=getDeck();if(!d)return emptyDeck();let p=deckMastery(d),f=ui.q.toLowerCase();let cards=d.cards.filter(c=>!f||`${c.term} ${c.definition} ${c.pinyin} ${c.notes}`.toLowerCase().includes(f));return `<div class="crumb"><button data-act="nav" data-page="library">My library</button>${icon('arrow')} ${esc(d.title)}</div><div class="row space-between wrap" style="margin-bottom:14px"><span class="pill purple">${esc(d.subject||'General')} ${d.folder?'· '+esc(d.folder):''}</span><div class="row wrap gap-sm"><button class="btn small" data-act="edit-deck">${icon('edit')} Edit set</button><button class="btn small" data-act="export-deck">${icon('download')} Export</button><button class="btn small danger" data-act="delete-deck">${icon('trash')}</button></div></div><div class="row space-between" style="align-items:center;gap:20px;margin-bottom:25px"><div class="deck-hero"><span class="deck-icon">📚</span><div><h1>${esc(d.title)}</h1><p class="muted">${esc(d.description||'Learn at your own pace.')}</p><div class="row wrap"><span class="pill">${d.cards.length} terms</span><span class="pill green">${d.cards.filter(due).length} due to review</span><span class="pill">${d.cards.filter(c=>c.starred).length} starred</span></div></div></div><div class="progress-ring" style="--p:${p}"><div><strong>${p}%</strong><small>mastered</small></div></div></div><div class="split"><div><section class="surface"><div class="section-heading"><h2>Choose a study mode</h2><div class="row wrap"><button class="btn small" data-act="start" data-mode="flash" data-scope="random">${icon('shuffle')} Random</button><button class="btn small" data-act="start" data-mode="learn" data-scope="starred">${icon('star')} Starred</button></div></div><div class="modes-grid">${modeButton('flash','cards','Flashcards','Flip & remember')}${modeButton('learn','brain','Learn','Smart mixed practice')}${modeButton('mc','test','MCQ','Unlimited multiple choice')}${hasHanziDeck(d)?modeButton('stroke','pen','Character writing','Chinese stroke practice'):''}${modeButton('write','pen','Write','Type the answer')}${modeButton('test','test','Practice test','Customizable exams')}${modeButton('match','game','Match','Beat the clock')}${modeButton('blocks','game','Blocks','Clear matching tiles')}${modeButton('charms','star','Charms','Collect charms with answers')}${modeButton('blast','zap','Blast','Save your ship from falling answers')}${modeButton('review','clock','Spaced review','Remember for longer')}${data.settings.showPronunciation?modeButton('listen','speaker','Listen & type','Audio spelling'):''}${modeButton('blitz','zap','Blitz','60-second challenge')}</div></section><section class="surface" style="margin-top:22px"><div class="section-heading"><div><h2>Terms in this set</h2><p class="muted small" style="margin-bottom:0">Edit your definitions and notes</p></div><button class="btn small primary" data-act="add-card">${icon('plus')} Add term</button></div><div class="search" style="max-width:100%;margin:14px 0"><span>${icon('search')}</span><input data-role="term-search" placeholder="Find a term…" value="${escAttr(ui.q)}"/></div>${cards.length?cards.map(c=>`<div class="term-row"><div><div class="term-name ${d.lang?.startsWith('zh')?'hanzi':''}">${esc(c.term)}</div>${data.settings.showPronunciation&&c.pinyin?`<div class="pinyin">${esc(c.pinyin)}</div>`:''}</div><div class="term-def">${esc(c.definition)}${c.notes?`<div class="small muted">${esc(c.notes)}</div>`:''}</div><div class="term-actions"><button class="icon-btn ${c.starred?'active':''}" data-act="star" data-id="${c.id}" aria-label="${c.starred?'Unstar':'Star'}">${icon('star')}</button><button class="icon-btn" data-act="edit-card" data-id="${c.id}" aria-label="Edit term">${icon('edit')}</button>${data.settings.showPronunciation?`<button class="icon-btn" data-act="speak" data-id="${c.id}" aria-label="Hear term">${icon('speaker')}</button>`:''}</div></div>`).join(''):`<p class="muted">No terms match your search.</p>`}</section></div><div><section class="surface"><h3>Your learning progress</h3><p class="muted small">Automatically tracked as you practise</p><div class="row space-between"><span>Cards mastered</span><strong>${d.cards.filter(c=>mastery(c)>=100).length} / ${d.cards.length}</strong></div><div class="bar" style="margin:9px 0 23px"><span style="width:${p}%"></span></div><div class="row space-between" style="margin-bottom:12px"><span class="muted">Due now</span><strong>${d.cards.filter(due).length}</strong></div><div class="row space-between" style="margin-bottom:12px"><span class="muted">Practised</span><strong>${d.cards.filter(c=>c.correct+c.wrong>0).length}</strong></div><div class="row space-between"><span class="muted">Starred</span><strong>${d.cards.filter(c=>c.starred).length}</strong></div><button class="btn soft" style="margin-top:19px;width:100%" data-act="start" data-mode="review">${icon('clock')} Review now</button></section>${deckInsights(d)}<section class="note-panel" style="margin-top:19px"><strong>💡 Study tip</strong><p style="margin:8px 0 0">Try Learn mode for quick questions, then Spaced review to remember cards longer. Optional language and audio tools can be enabled in Settings.</p></section><section class="surface" style="margin-top:19px"><h3>Study settings</h3><div class="field"><label for="direction">Question direction</label><select class="select" id="direction" data-setting="direction"><option value="forward" ${data.settings.direction==='forward'?'selected':''}>Term → meaning</option><option value="reverse" ${data.settings.direction==='reverse'?'selected':''}>Meaning → term</option></select></div>${data.settings.showPronunciation?`<div class="checklist"><input type="checkbox" id="autoSpeak" data-setting="autoSpeak" ${data.settings.autoSpeak?'checked':''}/><label for="autoSpeak">Speak terms automatically</label></div>`:'<p class="muted small">Audio and pronunciation tools are off by default. Enable them in Settings when needed.</p>'}</section></div></div>`}
function importPage(){return `<div class="eyebrow">BRING YOUR NOTES</div><h1>Import flashcards</h1><p class="muted">Copy terms from Quizlet, paste CSV/TSV, or restore an exported backup. Files are processed only in your browser.</p><div class="split"><div class="surface"><div class="section-heading"><h2>Paste your flashcards</h2><span class="pill green">No limits</span></div><div class="field"><label for="import-title">Set name</label><input class="input" id="import-title" placeholder="e.g. Marketing — Chapter 4" value="My imported flashcards"/></div><div class="field"><label for="import-folder">Folder</label><input class="input" id="import-folder" placeholder="e.g. Semester 2" value=""/></div><div class="field"><label for="import-text">Cards (one per line)</label><textarea class="textarea" id="import-text" rows="11" placeholder="Demand[TAB]Willingness and ability to buy&#10;Supply[TAB]Quantity offered for sale" style="min-height:215px"></textarea></div><div class="small muted" style="margin-bottom:18px">Use a Tab between the term and definition. Additional columns are optional. Comma-separated CSV with headings also works. Quizlet's tab-separated export can be pasted directly.</div><div class="row wrap"><button class="btn primary" data-act="import-text">${icon('upload')} Import cards</button><button class="btn" data-act="paste-demo">Paste example</button></div></div><div><div class="surface"><h3>Import from a file</h3><p class="muted small">Supported: .csv, .tsv, .txt and Recall Studio .json backup files.</p><div class="dropzone">${icon('upload')}<p style="margin:9px 0">Choose a file from your device</p><input type="file" id="import-file" accept=".csv,.tsv,.txt,.json,text/plain,text/csv,application/json"/></div></div><div class="surface" style="margin-top:18px"><h3>Your data stays yours</h3><p class="muted small">Export all your sets, learning history and settings to a single JSON file. Restore it on another device even without an internet connection.</p><button class="btn" data-act="backup">${icon('download')} Download full backup</button></div><div class="note-panel" style="margin-top:18px"><strong>How to migrate from Quizlet</strong><p style="margin:8px 0 0">Open your set in Quizlet → Export (if available) → copy the term/definition rows → paste above. You can also create a CSV in Excel, Google Sheets or Numbers and import it here.</p></div></div></div>`}
function settingsPage(){return `<div class="eyebrow">MAKE IT YOURS</div><h1>Settings</h1><p class="muted">Everything works locally. No account, tracker, ads or subscription.</p><div class="split"><div class="surface"><h2>Study preferences</h2><div class="field"><label>Question direction</label><select class="select" data-setting="direction"><option value="forward" ${data.settings.direction==='forward'?'selected':''}>Term → definition</option><option value="reverse" ${data.settings.direction==='reverse'?'selected':''}>Definition → term</option></select></div><div class="field"><label>Appearance</label><select class="select" data-setting="theme"><option value="light" ${data.settings.theme==='light'?'selected':''}>Light theme</option><option value="dark" ${data.settings.theme==='dark'?'selected':''}>Dark theme</option></select></div><div class="switch-row"><span><strong>Enable optional pronunciation tools</strong><div class="muted small">Show optional audio playback and manually entered pronunciation / transcription fields (no automatic transcription). Shortcut: Alt+P</div></span><input type="checkbox" data-setting="showPronunciation" ${data.settings.showPronunciation?'checked':''}/></div>${data.settings.showPronunciation?`<div class="switch-row"><span><strong>Auto-play pronunciation</strong><div class="muted small">Uses installed device voices when possible</div></span><input type="checkbox" data-setting="autoSpeak" ${data.settings.autoSpeak?'checked':''}/></div><div class="switch-row"><span><strong>Use transcription for listening answers</strong><div class="muted small">Accept the optional transcription when available</div></span><input type="checkbox" data-setting="listenPinyin" ${data.settings.listenPinyin?'checked':''}/></div>`:''}<div class="switch-row"><span><strong>Large study text</strong><div class="muted small">Also available from the study toolbar</div></span><input type="checkbox" data-setting="largeText" ${data.settings.largeText?'checked':''}/></div><div class="switch-row"><span><strong>Focus mode</strong><div class="muted small">Hide navigation while studying</div></span><input type="checkbox" data-setting="focusMode" ${data.settings.focusMode?'checked':''}/></div><div class="switch-row"><span><strong>Reduce animations</strong><div class="muted small">Simplify interface transitions</div></span><input type="checkbox" data-setting="calmMotion" ${data.settings.calmMotion?'checked':''}/></div><div class="switch-row"><span><strong>Sound effects</strong><div class="muted small">Audio cues for correct and incorrect answers</div></span><input type="checkbox" data-setting="sound" ${data.settings.sound?'checked':''}/></div><h3 style="margin-top:22px">Learn mode question types</h3>${[['mc','Multiple choice'],['write','Written answers'],['tf','True / false']].map(([v,k])=>`<div class="switch-row"><span>${k}</span><input type="checkbox" data-learn-type="${v}" ${data.settings.learnTypes.includes(v)?'checked':''}/></div>`).join('')}</div><div><div class="surface"><h2>Backup & privacy</h2><p class="muted small">Your decks are saved with browser storage (IndexedDB and a localStorage fallback where supported). Both are tied to this browser and this specific app URL/file origin. Clearing website data can erase them. Keep JSON backups.</p><div class="field"><label for="backup-days">Backup reminder</label><select class="select" id="backup-days" data-setting="backupReminderDays"><option value="7" ${Number(data.settings.backupReminderDays)===7?'selected':''}>Every 7 days</option><option value="14" ${Number(data.settings.backupReminderDays)===14?'selected':''}>Every 14 days</option><option value="30" ${Number(data.settings.backupReminderDays)===30?'selected':''}>Every 30 days</option><option value="0" ${Number(data.settings.backupReminderDays)===0?'selected':''}>Off</option></select></div><button class="btn primary" data-act="backup">${icon('download')} Back up everything</button><button class="btn" style="margin-top:10px" data-act="nav" data-page="import">${icon('upload')} Restore / import</button><div class="note-panel" style="margin-top:18px"><strong>Offline support</strong><p style="margin:7px 0 0">The desktop standalone HTML works without hosting. To install on iPhone or Android as an app, open the PWA folder from an HTTPS website once and choose “Add to Home Screen” or “Install app”. After installation, it works offline.</p></div></div><div class="surface" style="margin-top:18px"><h3>Keyboard shortcuts</h3><div class="hist-row"><span>Open shortcut help</span><span class="kbd">?</span></div><div class="hist-row"><span>Star current card</span><span class="kbd">F</span></div><div class="hist-row"><span>MCQ choice / game answers</span><span class="kbd">1–4</span></div><div class="hist-row"><span>Toggle optional pronunciation tools</span><span class="kbd">Alt+P</span></div><div class="hist-row"><span>Flip a flashcard</span><span class="kbd">Space</span></div><div class="hist-row"><span>Next card</span><span class="kbd">→</span></div><div class="hist-row"><span>Previous card</span><span class="kbd">←</span></div>${data.settings.showPronunciation?'<div class="hist-row"><span>Play pronunciation</span><span class="kbd">S</span></div>':''}<div class="hist-row"><span>Submit written answer</span><span class="kbd">Enter</span></div></div></div></div>`}
function historyHtml(limit=100){return data.history.slice(-limit).reverse().map(h=>`<div class="hist-row"><div><strong>${esc(getDeck(h.deckId)?.title||'Deleted set')}</strong><div class="muted small">${esc(h.mode.toUpperCase())} · ${fmtDate(h.at)}</div></div><div style="text-align:right"><strong>${h.correct}/${h.total}</strong><div class="muted small">${Math.round(h.duration/1000)} sec</div></div></div>`).join('')||'<p class="muted">Complete a quiz or review to see results here.</p>'}
function statsPage(){let all=data.decks.flatMap(d=>d.cards),right=all.reduce((n,c)=>n+(c.correct||0),0),wrong=all.reduce((n,c)=>n+(c.wrong||0),0);return `<div class="eyebrow">YOUR LEARNING JOURNEY</div><h1>Study analytics</h1><p class="muted">Progress is stored privately on this device.</p><div class="stats-grid">${statBlock('Study sessions',data.history.length,'brain')}${statBlock('Answers correct',right,'check')}${statBlock('Accuracy',right+wrong?Math.round(100*right/(right+wrong))+'%':'—','chart')}${statBlock('Due for review',totalDue(),'clock')}</div><div class="split"><div class="surface"><h2>Deck progress</h2>${data.decks.map(d=>`<div style="margin:21px 0"><div class="row space-between"><strong>${esc(d.title)}</strong><span class="muted">${deckMastery(d)}%</span></div><div class="bar" style="margin-top:9px"><span style="width:${deckMastery(d)}%"></span></div></div>`).join('')||'<p class="muted">No decks yet.</p>'}</div><div class="surface"><h2>Recent activity</h2>${historyHtml()}</div></div>`}
function startMode(mode){if(mode==='listen'&&!data.settings.showPronunciation){toast('Enable optional pronunciation tools in Settings first.');return}let d=getDeck();if(!d||!d.cards.length){toast('Add at least one card first.');return;}if(mode==='test'){ui.page='test';ui.test={deckId:d.id,count:Math.min(20,d.cards.length),types:['mc','write','tf'],questions:[],submitted:false,result:null,started:Date.now()};render();return}if(mode==='match'){ui.page='match';initMatch();return}let cards=mode==='review'?d.cards.filter(due):d.cards.slice();if(mode==='review'&&cards.length===0){toast('Nothing is due — showing your whole deck for extra practice.');cards=d.cards.slice()};if(mode==='blitz'&&d.cards.length<2){toast('Blitz needs two or more terms.');return}let ids=shuffle(cards.map(c=>c.id));ui.session={mode,deckId:d.id,ids,pos:0,right:0,wrong:0,attempts:{},start:Date.now(),flip:false,feedback:null,phase:'question',q:null,starOnly:false,blitzLeft:60,completed:0};ui.page='study';if(['learn','write','listen','blitz'].includes(mode))makeQuestion();if(mode==='blitz'){timerHandle=setInterval(()=>{if(!ui.session||ui.session.mode!=='blitz'){clearInterval(timerHandle);return}ui.session.blitzLeft--;if(ui.session.blitzLeft<=0){finishSession();return}let t=$('#blitz-clock');if(t)t.textContent=ui.session.blitzLeft+'s';},1000)}render();maybeAutoSpeak()}
function currentCard(){const s=ui.session;return getCard(s.ids[s.pos],getDeck(s.deckId))}
function promptText(card){return data.settings.direction==='forward'?card.term:card.definition}
function solutionText(card){return data.settings.direction==='forward'?card.definition:card.term}
function alternatives(card){let vals=[solutionText(card)];if(data.settings.direction==='forward'){if(card.accepted)vals.push(...card.accepted.split(/\s*[|\n]\s*/));vals.push(...card.definition.split(/\s*[;,]\s*/));vals.push(card.definition.replace(/\s*\([^)]*\)/g,'').trim())}return vals.map(v=>v.trim()).filter(Boolean)}
const norm=s=>String(s||'').normalize('NFKC').toLocaleLowerCase().replace(/[.!?！？。；;:,，、“”"'’()（）\s]+/g,' ').trim();
function isCorrect(input,card,listen=false){if(listen){let expected=data.settings.listenPinyin&&card.pinyin?card.pinyin:card.term;return norm(input)===norm(expected)}let a=norm(input);return !!a&&alternatives(card).some(x=>norm(x)===a)}
function listenExpected(card){return data.settings.listenPinyin&&card.pinyin?card.pinyin:card.term}
function questionChoices(card,kind='mc'){const d=getDeck(ui.session.deckId);const val=solutionText(card);let others=shuffle([...new Set(d.cards.filter(c=>c.id!==card.id).map(solutionText).filter(a=>a!==val))]);if(kind==='tf'){let yes=others.length===0||Math.random()>=.5;return {show:yes?val:others[0]||val,yes};}return shuffle([val,...others.slice(0,3)])}
function makeQuestion(){const s=ui.session;if(!s||s.pos>=s.ids.length){finishSession();return}let card=currentCard(),mode=s.mode,kind=mode==='write'?'write':mode==='listen'?'listen':mode==='blitz'?'mc':'mc';if(mode==='learn'){let kinds=data.settings.learnTypes?.length?data.settings.learnTypes:['mc'];kind=shuffle(kinds)[0];if(getDeck(s.deckId).cards.length===1&&kind==='mc')kind='write'}if(kind==='mc'&&getDeck(s.deckId).cards.length===1)kind='write';const choices=kind==='mc'?questionChoices(card):kind==='tf'?questionChoices(card,'tf'):null;s.q={kind,choices};s.phase='question';s.feedback=null;s.flip=false}
function updatePractice(card,correct){if(correct){card.correct=(card.correct||0)+1;card.streak=(card.streak||0)+1}else{card.wrong=(card.wrong||0)+1;card.streak=0}card.lastReviewed=Date.now();save()}
function answerPractice(value){const s=ui.session;if(!s||s.phase!=='question')return;let c=currentCard(),kind=s.q?.kind;let right=kind==='mc'?value===solutionText(c):kind==='tf'?(value==='true')===s.q.choices.yes:kind==='listen'?isCorrect(value,c,true):isCorrect(value,c);s.phase='feedback';s.feedback={right,value,solution:kind==='listen'?listenExpected(c):solutionText(c)};s.completed++;if(right){s.right++;cue(true)}else{s.wrong++;cue(false);if(s.mode==='learn'&&(s.attempts[c.id]||0)<2){s.ids.push(c.id);s.attempts[c.id]=(s.attempts[c.id]||0)+1}}updatePractice(c,right);if(s.mode==='blitz'&&right){nextQuestion();return}render();}
function nextQuestion(){let s=ui.session;if(!s)return;s.pos++;if(s.mode==='flash'||s.mode==='review'){s.flip=false;if(s.pos>=s.ids.length){finishSession();return}}else if(s.mode==='blitz'){if(s.pos>=s.ids.length){s.ids.push(...shuffle(getDeck(s.deckId).cards.map(c=>c.id)))}makeQuestion()}else{if(s.pos>=s.ids.length){finishSession();return}makeQuestion()}render();maybeAutoSpeak()}
function previousFlash(){let s=ui.session;if(!s||s.pos<=0)return;s.pos--;s.flip=false;render()}
function gradeReview(grade){let s=ui.session,c=currentCard();if(!s||s.mode!=='review'||!c)return;let good=grade!==0;updatePractice(c,good);if(grade===0){c.interval=0;c.ease=Math.max(1.3,(c.ease||2.5)-.2);c.due=Date.now()+60*1000}else if(grade===1){c.interval=Math.max(1,Math.ceil((c.interval||1)*1.2));c.ease=Math.max(1.3,(c.ease||2.5)-.15);c.due=Date.now()+c.interval*86400000}else if(grade===2){c.interval=c.interval?Math.max(2,Math.round(c.interval*(c.ease||2.5))):1;c.due=Date.now()+c.interval*86400000}else{c.interval=c.interval?Math.max(4,Math.round(c.interval*(c.ease||2.5)*1.3)):4;c.ease=Math.min(3.5,(c.ease||2.5)+.15);c.due=Date.now()+c.interval*86400000}save();s.completed++;if(good)s.right++;else s.wrong++;nextQuestion()}
function finishSession(){clearInterval(timerHandle);timerHandle=null;let s=ui.session;if(!s||s.phase==='result')return;s.phase='result';let total=s.right+s.wrong;if(total){data.history.push({deckId:s.deckId,mode:s.mode,correct:s.right,total,at:Date.now(),duration:Date.now()-s.start});if(data.history.length>800)data.history.splice(0,data.history.length-800)}save();render()}
function studyPage(){const s=ui.session;if(!s)return homePage();let d=getDeck(s.deckId);if(!d)return emptyDeck();if(s.phase==='result')return resultsPage(s.mode,s.right,s.wrong,s.start);let c=currentCard();if(!c)return resultsPage(s.mode,s.right,s.wrong,s.start);let isFlash=['flash','review'].includes(s.mode);let progress=s.mode==='blitz'?100*Math.max(0,60-s.blitzLeft)/60:Math.round(100*s.pos/s.ids.length);return `<div class="study-layout"><div class="crumb"><button data-act="open-deck" data-id="${d.id}">${esc(d.title)}</button>${icon('arrow')} ${esc(modeTitle(s.mode))}</div><div class="study-header"><div><div class="eyebrow">${esc(modeTitle(s.mode)).toUpperCase()}</div><h2>${esc(d.title)}</h2></div><div class="row gap-sm"><button class="btn small" data-act="restart">${icon('refresh')} <span class="hide-mobile">Restart</span></button><button class="icon-btn" data-act="open-deck" data-id="${d.id}" aria-label="Close session">${icon('close')}</button></div></div><div class="study-progress"><div class="bar"><span style="width:${progress}%"></span></div><small>${s.mode==='blitz'?`<span id="blitz-clock">${s.blitzLeft}s</span> left`:`${Math.min(s.pos+1,s.ids.length)} / ${s.ids.length}`}</small></div>${quickStudyToolbar(c)}${isFlash?flashView(s,c):questionView(s,c)}</div>`}
function modeTitle(m){return ({flash:'Flashcards',learn:'Learn',write:'Written practice',test:'Practice test',match:'Match',review:'Spaced review',listen:'Listen & type',blitz:'Blitz'})[m]||m}
function flashView(s,c){const flip=s.flip;return `<div class="study-card" data-act="flip" role="button" tabindex="0" aria-label="Flip flashcard"><button class="icon-btn in-card-star ${c.starred?'active':''}" data-act="star" data-id="${c.id}" aria-label="${c.starred?'Unstar':'Star'} this flashcard" title="Star flashcard (F)">${icon('star')}</button><span class="face-label">${flip?'BACK · DEFINITION':'FRONT · TERM'}</span><div class="study-word">${esc(flip?solutionText(c):promptText(c))}</div>${data.settings.showPronunciation&&!flip&&data.settings.direction==='forward'&&c.pinyin?`<div class="study-secondary">${esc(c.pinyin)}</div>`:''}${flip&&c.notes?`<div class="muted">${esc(c.notes)}</div>`:''}${c.image&&(!flip)?`<img alt="Card illustration" src="${safeImage(c.image)}" style="max-height:140px;border-radius:11px"/>`:''}${data.settings.showPronunciation?`<button class="icon-btn speak-float" data-act="speak" data-id="${c.id}" aria-label="Speak term">${icon('speaker')}</button>`:''}<div class="flip-note">Tap to flip <span class="kbd">Space</span></div></div><div class="study-controls"><button class="icon-btn" data-act="prev" ${s.pos===0?'disabled':''} aria-label="Previous card">${icon('back')}</button><button class="btn" data-act="flip">${icon('refresh')} Flip</button><button class="icon-btn" data-act="next" aria-label="Next card">${icon('arrow')}</button></div>${s.mode==='review'?`${s.flip?`<div class="surface" style="margin-top:21px;text-align:center"><p class="muted">How well did you remember this?</p><div class="row wrap" style="justify-content:center"><button class="btn danger" data-act="grade" data-grade="0">Again</button><button class="btn" data-act="grade" data-grade="1">Hard</button><button class="btn soft" data-act="grade" data-grade="2">Good</button><button class="btn primary" data-act="grade" data-grade="3">Easy</button></div></div>`:`<p class="center muted small" style="margin-top:20px">Flip the card, then rate your recall to schedule the next review.</p>`}`:`<p class="center muted small" style="margin-top:22px">Use <span class="kbd">←</span> <span class="kbd">→</span> to navigate${data.settings.showPronunciation?' · <span class="kbd">S</span> to hear pronunciation':''}</p>`}`}
function questionView(s,c){let q=s.q||{},kind=q.kind,show=s.phase==='feedback';let explain=show?`<div class="feedback ${s.feedback.right?'':'bad'}"><strong>${s.feedback.right?'✓ Correct!':'✗ Not quite'}</strong><small>Answer: ${esc(s.feedback.solution)}${data.settings.showPronunciation&&c.pinyin&&data.settings.direction==='reverse'?` · ${esc(c.pinyin)}`:''}</small>${c.notes?`<div class="small">${esc(c.notes)}</div>`:''}</div><div class="row" style="justify-content:flex-end"><button class="btn primary" data-act="next">${s.pos+1>=s.ids.length&&s.mode!=='blitz'?'See results':'Continue'} ${icon('arrow')}</button></div>`:'';
return `<div class="study-area"><div class="inline-card question-surface"><button class="icon-btn in-card-star ${c.starred?'active':''}" data-act="star" data-id="${c.id}" aria-label="${c.starred?'Unstar':'Star'} this term" title="Star term (F)">${icon('star')}</button><div class="question-heading">${kind==='listen'?'Listen and type what you hear':kind==='tf'?'Is this a correct pair?':data.settings.direction==='forward'?'What does this mean?':'Which term matches?'} </div>${kind==='listen'?`<div class="center" style="padding:22px 0"><button class="btn soft" data-act="speak" data-id="${c.id}" style="width:96px;height:96px;border-radius:50%">${icon('speaker')}</button><p class="muted small" style="margin-top:15px">Tap to play the term aloud</p></div>`:`<div class="question-word">${esc(promptText(c))}</div>${data.settings.showPronunciation&&c.pinyin&&data.settings.direction==='forward'&&kind!=='tf'?`<div class="question-sub">${esc(c.pinyin)}</div>`:''}`}${kind==='mc'?`<div class="answers-grid">${q.choices.map((x,i)=>`<button class="option ${show?(x===solutionText(c)?'correct':x===s.feedback.value?'incorrect':''):''}" data-act="answer" data-value="${escAttr(x)}" ${show?'disabled':''}><span class="letter">${'ABCD'[i]}</span><span>${esc(x)}</span></button>`).join('')}</div>`:kind==='tf'?`<div class="surface center" style="background:var(--bg);margin:24px 0;padding:23px"><span class="muted small">Proposed answer</span><div style="font-size:24px;font-weight:750;margin-top:9px">${esc(q.choices.show)}</div></div><div class="answers-grid tf-answers">${['false','true'].map(x=>`<button class="option ${show?((x==='true')===q.choices.yes?'correct':x===s.feedback.value?'incorrect':''):''}" data-act="answer" data-value="${x}" ${show?'disabled':''}>${x==='true'?icon('check'):icon('close')} ${x==='true'?'True':'False'}</button>`).join('')}</div>`:`<form id="answer-form"><label for="answer-text" class="muted small">${kind==='listen'?(data.settings.listenPinyin&&c.pinyin?'Type the optional transcription':'Type what you heard'):'Type your answer'}</label><input class="write-input" id="answer-text" name="answer" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="Your answer…" ${show?'disabled':''} style="margin:10px 0"/><div class="row" style="justify-content:flex-end"><button class="btn primary" type="submit" ${show?'disabled':''}>Check answer ${icon('check')}</button></div></form>`}${explain}</div><div class="center muted small" style="margin-top:20px">${s.right} correct · ${s.wrong} to practise again ${s.mode==='blitz'?'· Time matters!':''}</div></div>`}
function resultsPage(mode,right,wrong,start,extra=''){const total=right+wrong,pct=total?Math.round(right*100/total):0,seconds=Math.max(0,Math.round((Date.now()-start)/1000));return `<div class="study-layout"><div class="surface center" style="padding:36px 26px"><div class="trophy">${pct>=80?'🏆':pct>=50?'🌟':'💪'}</div><div class="eyebrow" style="margin-top:12px">SESSION COMPLETE</div><h1 style="margin:9px 0">${pct>=80?'Great work!':pct>=50?'Keep it going!':'Practice makes progress.'}</h1><p class="muted">${esc(modeTitle(mode))} · ${esc(getDeck()?.title||'Study set')}</p><div class="result-score">${pct}%</div><div class="result-metrics"><div><strong>${right}</strong><small>Correct</small></div><div><strong>${wrong}</strong><small>Incorrect</small></div><div><strong>${seconds}s</strong><small>Elapsed</small></div></div>${extra}<div class="row wrap" style="justify-content:center;margin-top:22px"><button class="btn primary" data-act="restart">${icon('refresh')} Study again</button><button class="btn" data-act="open-deck" data-id="${ui.deckId}">Return to set</button></div></div></div>`}
function initMatch(){let d=getDeck(),pool=shuffle(d.cards).slice(0,Math.min(6,d.cards.length));if(pool.length<2){toast('Matching needs at least two cards.');nav('deck');return}ui.match={deckId:d.id,started:Date.now(),done:[],selected:null,mistakes:0,cols:[shuffle(pool.map(c=>({id:c.id,side:'term',text:c.term}))),shuffle(pool.map(c=>({id:c.id,side:'definition',text:c.definition})))],finished:false};timerHandle=setInterval(()=>{if(!ui.match||ui.match.finished||ui.page!=='match'){clearInterval(timerHandle);return}const el=$('#match-clock');if(el)el.textContent='⏱ '+Math.round((Date.now()-ui.match.started)/1000)+'s'},1000);render()}
function matchPage(){let m=ui.match;if(!m)return deckPage();let d=getDeck(m.deckId),total=m.cols[0].length,elapsed=Math.round((Date.now()-m.started)/1000);if(m.finished){let best=data.bestMatch[d.id];return `<div class="study-layout"><div class="surface center" style="padding:36px"><div class="trophy">🏅</div><h1>Perfect match!</h1><div class="result-score">${elapsed}s</div><p class="muted">${m.mistakes} mismatches · Best time: ${best}s</p><div class="row wrap" style="justify-content:center"><button class="btn primary" data-act="start" data-mode="match">Play again</button><button class="btn" data-act="open-deck" data-id="${d.id}">Back to set</button></div></div></div>`}return `<div class="study-layout"><div class="crumb"><button data-act="open-deck" data-id="${d.id}">${esc(d.title)}</button>${icon('arrow')} Match</div><div class="row space-between"><div><div class="eyebrow">MATCH GAME</div><h1>Make the pairs</h1><p class="muted">Tap the matching term and definition.</p></div><div class="pill purple" id="match-clock">⏱ ${elapsed}s</div></div><div class="study-progress"><div class="bar"><span style="width:${100*m.done.length/total}%"></span></div><small>${m.done.length}/${total} pairs</small></div><div class="pair-grid"><div>${m.cols[0].map((c,i)=>matchTile(c,0,i,m)).join('')}</div><div>${m.cols[1].map((c,i)=>matchTile(c,1,i,m)).join('')}</div></div><div class="row space-between"><span class="muted small">Mistakes: ${m.mistakes}</span><button class="btn" data-act="start" data-mode="match">${icon('refresh')} Restart</button></div></div>`}
function matchTile(c,col,i,m){let matched=m.done.includes(c.id),sel=m.selected&&m.selected.col===col&&m.selected.i===i;return `<button class="match-item ${matched?'matched':''} ${sel?'selected':''}" style="width:100%;margin-bottom:10px" data-act="match-tile" data-col="${col}" data-index="${i}" ${matched?'disabled':''}>${esc(c.text)}</button>`}
function clickMatch(col,i){let m=ui.match;if(!m||m.finished)return;let c=m.cols[col][i];if(m.done.includes(c.id))return;if(!m.selected){m.selected={col,i,id:c.id};render();return}let prev=m.selected;if(prev.col===col){m.selected={col,i,id:c.id};render();return}if(prev.id===c.id){m.done.push(c.id);cue(true);m.selected=null;if(m.done.length===m.cols[0].length){m.finished=true;clearInterval(timerHandle);let seconds=Math.round((Date.now()-m.started)/1000);data.bestMatch[m.deckId]=Math.min(data.bestMatch[m.deckId]||Infinity,seconds);data.history.push({deckId:m.deckId,mode:'match',correct:m.done.length,total:m.done.length,at:Date.now(),duration:Date.now()-m.started});save()}}else{m.mistakes++;m.selected=null;cue(false)}render()}
function testPage(){let t=ui.test;if(!t)return deckPage();let d=getDeck(t.deckId);if(t.submitted)return testResultsPage(t);if(!t.questions.length)return `<div class="study-layout"><div class="crumb"><button data-act="open-deck" data-id="${d.id}">${esc(d.title)}</button>${icon('arrow')} Practice test</div><div class="surface"><div class="eyebrow">BUILD YOUR EXAM</div><h1>Practice test</h1><p class="muted">Choose the number and style of questions. This is completely free.</p><div class="field"><label>Questions (maximum ${d.cards.length})</label><input class="input" type="number" min="1" max="${d.cards.length}" value="${t.count}" id="test-count"/></div><strong>Include question types</strong><div class="switch-row"><span>Multiple choice</span><input type="checkbox" class="test-type" value="mc" checked/></div><div class="switch-row"><span>Written answers</span><input type="checkbox" class="test-type" value="write" checked/></div><div class="switch-row"><span>True or false</span><input type="checkbox" class="test-type" value="tf" checked/></div><div style="margin-top:21px"><button class="btn primary" data-act="create-test">Start test ${icon('arrow')}</button></div></div></div>`;return `<div class="study-layout"><div class="crumb"><button data-act="open-deck" data-id="${d.id}">${esc(d.title)}</button>${icon('arrow')} Practice test</div><div class="heading-row"><div><div class="eyebrow">YOUR EXAM</div><h1>Practice test</h1><p class="muted">${t.questions.length} questions · Take your time</p></div><button class="btn" data-act="reset-test">Reset</button></div><form id="test-form">${t.questions.map((q,i)=>{let c=getCard(q.cardId,d);return `<div class="test-item"><div class="eyebrow">QUESTION ${i+1} · ${q.kind==='mc'?'MULTIPLE CHOICE':q.kind==='tf'?'TRUE OR FALSE':'WRITTEN'}</div><h3>${esc(promptText(c))}</h3>${q.kind==='tf'?`<p class="pill">Proposed: ${esc(q.choices.show)}</p>`:''}${q.kind==='write'?`<input class="input" name="a_${i}" placeholder="Type your answer" autocomplete="off"/>`:`<div class="test-choices ${q.kind==='tf'?'tf-choices':''}">${(q.kind==='mc'?q.choices:['false','true']).map((x,k)=>`<label><input type="radio" name="a_${i}" value="${escAttr(x)}"/><span>${esc(q.kind==='tf'?(x==='true'?'True':'False'):x)}</span></label>`).join('')}</div>`}</div>`}).join('')}<button class="btn primary" type="submit" style="width:100%;margin-top:10px">Submit test & see results ${icon('check')}</button></form></div>`}
function createTest(){const t=ui.test,d=getDeck(t.deckId);let count=Math.max(1,Math.min(d.cards.length,Number($('#test-count')?.value)||10)),types=[...document.querySelectorAll('.test-type:checked')].map(e=>e.value);if(!types.length){toast('Choose at least one question type.');return}t.count=count;t.types=types;t.questions=shuffle(d.cards).slice(0,count).map(c=>{let kind=shuffle(types)[0];if(kind==='mc'&&d.cards.length<2)kind='write';return {cardId:c.id,kind,choices:kind==='mc'?testOptions(c,d):kind==='tf'?testTF(c,d):null}});t.started=Date.now();render()}
function testOptions(card,d){let v=solutionText(card),o=shuffle([...new Set(d.cards.filter(c=>c.id!==card.id).map(solutionText).filter(x=>x!==v))]);return shuffle([v,...o.slice(0,3)])}
function testTF(card,d){let o=d.cards.filter(c=>c.id!==card.id),yes=!o.length||Math.random()>=.5;return {yes,show:yes?solutionText(card):solutionText(shuffle(o)[0])}}
function submitTest(form){let t=ui.test,d=getDeck(t.deckId),fd=new FormData(form),right=0;let review=[];t.questions.forEach((q,i)=>{let c=getCard(q.cardId,d),v=String(fd.get(`a_${i}`)||'');let ok=q.kind==='mc'?v===solutionText(c):q.kind==='tf'?(v==='true')===q.choices.yes&&v!=='':isCorrect(v,c);right+=ok?1:0;updatePractice(c,ok);review.push({q,card:c,answer:v,ok})});t.submitted=true;t.result={right,wrong:t.questions.length-right,review};data.history.push({deckId:d.id,mode:'test',correct:right,total:t.questions.length,at:Date.now(),duration:Date.now()-t.started});save();render()}
function testResultsPage(t){let r=t.result,d=getDeck(t.deckId);return `<div class="study-layout"><div class="surface center"><div class="trophy">${r.right>=t.questions.length*.8?'🏆':'📚'}</div><div class="eyebrow">TEST RESULTS</div><h1>${Math.round(100*r.right/t.questions.length)}% score</h1><p class="muted">${r.right} correct out of ${t.questions.length}</p><div class="row wrap" style="justify-content:center"><button class="btn primary" data-act="reset-test">Take another test</button><button class="btn" data-act="open-deck" data-id="${d.id}">Back to set</button></div></div><h2 style="margin-top:25px">Review your answers</h2>${r.review.map((a,i)=>`<div class="test-item"><div class="row space-between"><strong>Question ${i+1}</strong><span class="pill ${a.ok?'green':'red'}">${a.ok?'Correct':'Incorrect'}</span></div><h3 style="margin-top:12px">${esc(promptText(a.card))}</h3><div class="muted small">Your answer: ${esc(a.answer||'(blank)')}</div><div class="small" style="color:var(--green);margin-top:6px">Correct answer: ${esc(solutionText(a.card))}</div></div>`).join('')}</div>`}
function maybeAutoSpeak(){if(!data.settings.showPronunciation||!data.settings.autoSpeak)return;let s=ui.session;if(s&&!['learn','blitz'].includes(s.mode))setTimeout(()=>{if(ui.session===s)playSpeech(currentCard()?.term,getDeck(s.deckId)?.lang||'en-US')},250)}
function playSpeech(word,lang){if(!word)return;if(!('speechSynthesis'in window)){toast('Speech is not supported by this browser.');return}try{speechSynthesis.cancel();let u=new SpeechSynthesisUtterance(word);u.lang=lang||'en-US';u.rate=.85;let voices=speechSynthesis.getVoices();let v=voices.find(v=>v.lang.toLowerCase().startsWith((lang||'en').slice(0,2).toLowerCase())&&v.localService)||voices.find(v=>v.lang.toLowerCase().startsWith((lang||'en').slice(0,2).toLowerCase()));if(v)u.voice=v;speechSynthesis.speak(u)}catch(e){toast('Pronunciation unavailable on this device.')}}
let audioCtx;function cue(ok){if(!data.settings.sound)return;try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;audioCtx=audioCtx||new C();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.value=ok?660:230;g.gain.setValueAtTime(.035,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.16);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+.17)}catch(e){}}
function renderModal(){const root=$('#modal-root');if(!ui.modal){root.innerHTML='';return}let d=getDeck(),c=ui.editing?getCard(ui.editing):null,body='';if(ui.modal==='help'){body=`<div class="modal-heading"><div><h2>Keyboard shortcuts</h2><p class="muted small">You can study without the mouse. Shortcuts do not interrupt typing.</p></div><button class="icon-btn" data-act="close-modal">${icon('close')}</button></div>${[['Space','Flip current card'],['← / →','Previous / next flashcard'],['1–4','Choose multiple-choice option'],['Enter','Continue after feedback / check written answer'],['F','Star or unstar the current card'],['R','Shuffle the current flashcard session'],['S','Speak when pronunciation is enabled'],['Alt + P','Toggle pronunciation accessibility'],['?','Show keyboard help'],['Esc','Close this window']].map(([k,v])=>`<div class="hist-row"><span>${v}</span><span class="kbd">${k}</span></div>`).join('')}`;}else if(ui.modal==='deck'){let ed=ui.editing==='deck',set=ed?d:null;body=`<div class="modal-heading"><div><h2>${ed?'Edit study set':'Create a study set'}</h2><p class="muted small">Organize your cards and give them a home.</p></div><button class="icon-btn" data-act="close-modal">${icon('close')}</button></div><form id="deck-form"><div class="field"><label>Title *</label><input class="input" name="title" required maxlength="140" placeholder="e.g. Economics — Chapter 1" value="${escAttr(set?.title||'')}"/></div><div class="field"><label>Description</label><textarea class="textarea" name="description" placeholder="What will you learn?" style="min-height:70px">${esc(set?.description||'')}</textarea></div><div class="two-cols"><div class="field"><label>Folder</label><input class="input" name="folder" placeholder="e.g. University" value="${escAttr(set?.folder||'')}"/></div><div class="field"><label>Subject</label><select class="select" name="subject">${['Languages','Science','Math','History','Business','General','Other'].map(x=>`<option ${x===(set?.subject||'General')?'selected':''}>${x}</option>`).join('')}</select></div></div>${data.settings.showPronunciation?`<div class="field"><label>Speech language</label><select class="select" name="lang">${[['zh-CN','Chinese (Mandarin)'],['en-US','English (US)'],['hi-IN','Hindi'],['fr-FR','French'],['es-ES','Spanish'],['de-DE','German'],['ja-JP','Japanese'],['ko-KR','Korean'],['it-IT','Italian'],['other','Other / device default']].map(([k,x])=>`<option value="${k}" ${k===(set?.lang||'en-US')?'selected':''}>${x}</option>`).join('')}</select></div>`:''}<div class="modal-footer"><button type="button" class="btn" data-act="close-modal">Cancel</button><button class="btn primary" type="submit">${ed?'Save changes':'Create set'}</button></div></form>`}else if(ui.modal==='card'){let ed=!!c;body=`<div class="modal-heading"><div><h2>${ed?'Edit flashcard':'Add a flashcard'}</h2><p class="muted small">Make cards about any subject. Add optional details only if you need them.</p></div><button class="icon-btn" data-act="close-modal">${icon('close')}</button></div><form id="card-form"><div class="field"><label>Term *</label><input class="input" name="term" required placeholder="e.g. Opportunity cost" value="${escAttr(c?.term||'')}"/></div><div class="field"><label>Definition *</label><textarea class="textarea" name="definition" required placeholder="Value of the next best alternative forgone" style="min-height:70px">${esc(c?.definition||'')}</textarea></div><div class="two-cols">${data.settings.showPronunciation?`<div class="field"><label>Optional transcription</label><input class="input" name="pinyin" placeholder="Add if useful" value="${escAttr(c?.pinyin||'')}"/></div>`:''}<div class="field"><label>Other accepted answers (use | to separate)</label><input class="input" name="accepted" placeholder="Alternative definition | Synonym" value="${escAttr(c?.accepted||'')}"/></div></div><div class="field"><label>Extra notes / explanation</label><textarea class="textarea" name="notes" placeholder="Example, grammar note, memory aid…" style="min-height:72px">${esc(c?.notes||'')}</textarea></div><div class="field"><label>Optional image (saved locally; small files recommended)</label><input class="input" type="file" id="card-image" accept="image/png,image/jpeg,image/webp,image/gif"/></div>${c?.image?`<div class="row"><img alt="Current card image" src="${safeImage(c.image)}" style="height:65px;border-radius:8px"/><button class="btn danger small" data-act="remove-card-image" type="button">Remove image</button></div>`:''}<div class="modal-footer">${ed?`<button type="button" class="btn danger" data-act="delete-card" data-id="${c.id}" style="margin-right:auto">Delete term</button>`:''}<button type="button" class="btn" data-act="close-modal">Cancel</button><button class="btn primary" type="submit">${ed?'Save term':'Add card'}</button></div></form>`}else if(ui.modal==='export'){body=`<div class="modal-heading"><div><h2>Export your set</h2><p class="muted small">Share your vocabulary between phones and computers.</p></div><button class="icon-btn" data-act="close-modal">${icon('close')}</button></div><p><strong>${esc(d?.title||'Study set')}</strong> · ${d?.cards.length||0} cards</p><div class="row wrap"><button class="btn primary" data-act="download-deck-json">${icon('download')} Study set JSON</button><button class="btn" data-act="download-deck-csv">${icon('download')} CSV / Excel</button><button class="btn" data-act="copy-deck">Copy as text</button></div><p class="muted small" style="margin-top:19px">JSON keeps card progress, stars, notes and images. CSV is ideal for sharing vocabulary with other apps.</p>`}root.innerHTML=`<div class="modal-backdrop" data-act="close-modal" role="presentation"><div class="modal" role="dialog" aria-modal="true" aria-label="${escAttr(ui.modal)}" data-no-close="1">${body}</div></div>`;root.querySelector('.input')?.focus()}
function safeImage(s){return /^data:image\/(png|jpeg|webp|gif);base64,/i.test(s||'')?escAttr(s):''}
function closeModal(){ui.modal='';ui.editing='';pendingFileImage=null;renderModal()}
function formDeck(fd){let title=String(fd.get('title')||'').trim();if(!title){toast('A title is required.');return}let ed=ui.editing==='deck',d=ed?getDeck():{id:uid(),created:Date.now(),cards:[]};d.title=title;d.description=String(fd.get('description')||'').trim();d.folder=String(fd.get('folder')||'').trim();d.subject=String(fd.get('subject')||'General');d.lang=String(fd.get('lang')||d.lang||'en-US');if(!ed)data.decks.unshift(d);ui.deckId=d.id;ui.q='';save();closeModal();nav('deck');toast(ed?'Study set updated.':'New study set created.')}
async function fileDataUrl(file){if(!file)return null;if(file.size>1.5*1024*1024)throw Error('Image is too large. Please choose one smaller than 1.5 MB.');if(!/^image\/(png|jpeg|webp|gif)$/.test(file.type))throw Error('Choose a PNG, JPEG, WebP or GIF.');return new Promise((res,rej)=>{let r=new FileReader();r.onload=()=>res(r.result);r.onerror=()=>rej(Error('Could not read the image.'));r.readAsDataURL(file)})}
async function formCard(fd){let term=String(fd.get('term')||'').trim(),definition=String(fd.get('definition')||'').trim();if(!term||!definition){toast('Both term and definition are required.');return}let d=getDeck(),c=ui.editing?getCard(ui.editing):null;try{let f=$('#card-image')?.files?.[0],img=f?await fileDataUrl(f):null;if(!c){c=mkCard(term,definition);d.cards.push(c)}c.term=term;c.definition=definition;if(data.settings.showPronunciation)c.pinyin=String(fd.get('pinyin')||'').trim();c.accepted=String(fd.get('accepted')||'').trim();c.notes=String(fd.get('notes')||'').trim();if(img)c.image=img;if(pendingFileImage==='remove')c.image='';save();closeModal();render();toast('Flashcard saved.')}catch(e){toast(e.message||'Could not save card.')}}
function filenameSafe(s){return String(s).normalize('NFKD').replace(/[^a-z0-9_-]+/gi,'_').slice(0,54)||'flashcards'}
function download(name,body,mime){const blob=new Blob([body],{type:mime});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),6000)}
function backup(){data.lastBackupAt=Date.now();data.backupSnoozedUntil=0;save();download('recall_studio_full_backup_'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(data,null,2),'application/json');render();toast('Backup download started. Keep your JSON file somewhere safe.')}
function downloadDeck(json){let d=getDeck();if(!d)return;if(json){download(filenameSafe(d.title)+'.json',JSON.stringify({version:1,type:'recall-studio-deck',deck:d},null,2),'application/json')}else{const quote=s=>'"'+String(s||'').replaceAll('"','""')+'"';let cols=data.settings.showPronunciation?['Term','Definition','Transcription','Notes','Accepted answers']:['Term','Definition','Notes','Accepted answers'];let csv=[cols.map(quote).join(','),...d.cards.map(c=>(data.settings.showPronunciation?[c.term,c.definition,c.pinyin,c.notes,c.accepted]:[c.term,c.definition,c.notes,c.accepted]).map(quote).join(','))].join('\r\n');download(filenameSafe(d.title)+'.csv','\ufeff'+csv,'text/csv;charset=utf-8')}closeModal();toast('Study set exported.')}
function validateDeck(d){if(!d||typeof d!=='object'||!Array.isArray(d.cards))throw Error('File does not contain a valid study set.');let newDeck={id:uid(),title:String(d.title||'Imported set').slice(0,140),description:String(d.description||''),folder:String(d.folder||''),subject:String(d.subject||'General'),lang:String(d.lang||'en-US'),created:Date.now(),cards:[]};newDeck.cards=d.cards.filter(x=>x&&x.term!=null&&x.definition!=null).map(c=>({...mkCard(c.term,c.definition,c.pinyin||'',c.notes||''),accepted:String(c.accepted||''),image:/^data:image\/(png|jpeg|webp|gif);base64,/i.test(c.image||'')?c.image:'',starred:!!c.starred,correct:Number(c.correct)||0,wrong:Number(c.wrong)||0,streak:Number(c.streak)||0,ease:Number(c.ease)||2.5,interval:Number(c.interval)||0,due:Number(c.due)||0,lastReviewed:Number(c.lastReviewed)||0}));return newDeck}
function importJSON(text){let obj=JSON.parse(text);if(obj.type==='recall-studio-deck'||(obj.cards&&!obj.decks)){let d=validateDeck(obj.deck||obj);data.decks.unshift(d);ui.deckId=d.id;save();nav('deck');toast(`Imported ${d.cards.length} cards.`);return}if(Array.isArray(obj.decks)){if(!confirm('Restore this full backup? This REPLACES all current decks, history and settings on this device. Export your current backup first if needed.'))return;let imported=obj.decks.map(validateDeck);data=normalizeData({...initial(),decks:imported,settings:{...initial().settings,...obj.settings,showPronunciation:obj.settings?.showPronunciation===true},history:Array.isArray(obj.history)?obj.history:[],mistakeLog:Array.isArray(obj.mistakeLog)?obj.mistakeLog:[],arcadeBest:obj.arcadeBest||{},bestMatch:obj.bestMatch||{},createdAt:Number(obj.createdAt)||Date.now(),lastBackupAt:Number(obj.lastBackupAt)||0});const ids=new Map(obj.decks.map((d,i)=>[d.id,imported[i].id]));data.history=data.history.map(h=>({...h,deckId:ids.get(h.deckId)||h.deckId}));ui.deckId=data.decks[0]?.id||'';save();nav('library');toast('Full backup restored.');return}throw Error('Unrecognized JSON backup format.')}
function parseDelimited(text){const first=String(text).trim().split(/\r?\n/,1)[0]||'';const delim=first.includes('\t')?'\t':first.includes(',')?',':first.includes('|')?'|':'\t';let rows=[],row=[],field='',quote=false;for(let i=0;i<text.length;i++){let x=text[i];if(x==='"'){if(quote&&text[i+1]==='"'){field+='"';i++}else quote=!quote}else if(x===delim&&!quote){row.push(field);field=''}else if((x==='\n'||x==='\r')&&!quote){if(x==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(v=>v.trim()))rows.push(row);row=[];field=''}else field+=x}row.push(field);if(row.some(v=>v.trim()))rows.push(row);
 rows=rows.map(r=>r.map(x=>x.trim())).filter(r=>r[0]&&r[1]);
 const hasHeader=rows.length>0&&/^(term|word|front|question|character)$/i.test(rows[0][0])&&/^(definition|meaning|back|answer)$/i.test(rows[0][1]);
 const headers=hasHeader?rows.shift().map(h=>h.toLowerCase()):null;
 return {rows,headers};
}
function importText(text,title='Imported flashcards',folder=''){
 if(text.trim().startsWith('{')){importJSON(text);return}
 const {rows,headers}=parseDelimited(text);
 if(!rows.length){toast('No cards found. Separate term and definition with a Tab or CSV comma.');return}
 const findHeader=(names)=>headers?headers.findIndex(h=>names.includes(h)):-1;
 const notesIdx=findHeader(['notes','note','explanation']);
 const transcriptionIdx=findHeader(['pinyin','transcription','pronunciation','romanization']);
 const acceptedIdx=findHeader(['accepted answers','accepted','alternatives']);
 const cards=rows.map(row=>{
   const [term,def]=row;
   const pinyin=transcriptionIdx>=0?row[transcriptionIdx]||'':!headers&&data.settings.showPronunciation?row[2]||'':'';
   const notes=notesIdx>=0?row[notesIdx]||'':!headers?(data.settings.showPronunciation?row[3]:row[2])||'':'';
   const accepted=acceptedIdx>=0?row[acceptedIdx]||'':!headers?(data.settings.showPronunciation?row[4]:row[3])||'':'';
   const c=mkCard(term,def,pinyin,notes);c.accepted=accepted;return c;
 });
 let d={id:uid(),title:title||'Imported flashcards',description:'Imported into Recall Studio',folder,subject:'General',lang:'en-US',created:Date.now(),cards};
 data.decks.unshift(d);ui.deckId=d.id;save();nav('deck');toast(`Imported ${d.cards.length} cards. Ready to study!`);
}
async function importFile(file){if(!file)return;try{if(file.size>8*1024*1024)throw Error('Please use a file smaller than 8 MB.');const text=await file.text();if(file.name.toLowerCase().endsWith('.json'))importJSON(text);else importText(text,file.name.replace(/\.[^.]+$/,''),$('#import-folder')?.value||'');}catch(e){toast('Import failed: '+(e.message||'Invalid file'))}}
function deleteDecksByIds(ids){
 const targets=data.decks.filter(d=>ids.includes(d.id));
 if(!targets.length)return;
 const names=targets.length===1?`“${targets[0].title}” (${targets[0].cards.length} cards)`: `${targets.length} selected study sets (${targets.reduce((n,d)=>n+d.cards.length,0)} cards)`;
 if(!confirm(`Permanently delete ${names} from this device, including their saved study results?\n\nThis cannot be undone. Export a backup first if you might need them.`))return;
 const gone=new Set(targets.map(d=>d.id));
 data.decks=data.decks.filter(d=>!gone.has(d.id));
 data.history=data.history.filter(h=>!gone.has(h.deckId));
 data.mistakeLog=(data.mistakeLog||[]).filter(m=>!gone.has(m.deckId));
 for(const id of gone){delete data.bestMatch[id];for(const k of Object.keys(data.arcadeBest||{}))if(k.startsWith(id+':'))delete data.arcadeBest[k]}
 ui.libraryFilters.selected=ui.libraryFilters.selected.filter(id=>!gone.has(id));
 ui.libraryFilters.selectMode=false;
 if(gone.has(ui.deckId))ui.deckId=data.decks[0]?.id||'';
 if(data.decks.every(d=>d.folder!==ui.filter))ui.filter='all';
 save();nav('library');toast(`${targets.length} study ${targets.length===1?'set':'sets'} deleted.`);
}
function removeDeck(id=ui.deckId){deleteDecksByIds([id])}

function removeCard(id){let d=getDeck(),c=getCard(id);if(!d||!c)return;if(!confirm(`Delete the term "${c.term}"?`))return;d.cards=d.cards.filter(x=>x.id!==id);save();closeModal();render();toast('Flashcard deleted.')}
function copyDeck(){let d=getDeck(),txt=d.cards.map(c=>(data.settings.showPronunciation?[c.term,c.definition,c.pinyin]:[c.term,c.definition]).filter(Boolean).join('\t')).join('\n');if(navigator.clipboard?.writeText){navigator.clipboard.writeText(txt).then(()=>toast('Cards copied to clipboard.')).catch(()=>toast('Clipboard permission denied; try exporting a CSV.'))}else toast('Clipboard is not supported; export a CSV instead.')}

/* v3 — independent local games, per-deck stats and mistake replay. No network dependencies. */
function learningCards(d){return d.cards.filter(c=>(c.correct||0)+(c.wrong||0)>0&&mastery(c)<100)}
function setMetrics(d){const right=d.cards.reduce((n,c)=>n+(c.correct||0),0),wrong=d.cards.reduce((n,c)=>n+(c.wrong||0),0);return {right,wrong,accuracy:right+wrong?Math.round(right*100/(right+wrong)):null,mastered:d.cards.filter(c=>mastery(c)>=100).length,learning:learningCards(d).length,unseen:d.cards.filter(c=>!(c.correct||c.wrong)).length,starred:d.cards.filter(c=>c.starred).length}}
function recentMistakes(d){return (data.mistakeLog||[]).filter(m=>!d||m.deckId===d.id).slice(-10).reverse()}
function shortTerms(s,n=48){s=String(s??'');return s.length>n?s.slice(0,n-1)+'…':s}
function deckCard(d){
 const p=deckMastery(d),m=setMetrics(d),inLibrary=ui.page==='library',selecting=inLibrary&&ui.libraryFilters.selectMode,selected=ui.libraryFilters.selected.includes(d.id);
 const title=esc(d.title),id=escAttr(d.id);
 return `<article class="deck-card ${selected?'deck-selected':''} ${selecting?'deck-selecting':''}" data-act="${selecting?'select-deck':'open-deck'}" data-id="${id}" tabindex="0" role="button" aria-label="${selecting?(selected?'Deselect ':'Select '):'Open '}${escAttr(d.title)}">
   <div class="row space-between deck-card-head"><span class="deck-icon">📚</span>
   <span class="row gap-sm" style="margin-left:auto">${inLibrary?selecting?`<span class="selection-indicator ${selected?'selected':''}" aria-hidden="true">${selected?'✓':''}</span>`:`<button type="button" class="deck-trash" data-act="delete-deck-id" data-id="${id}" title="Delete ${escAttr(d.title)}" aria-label="Delete ${escAttr(d.title)}">${icon('trash')}</button>`:''}<span class="pill">${esc(d.subject||'General')}</span></span></div>
   <div class="grow"><h3>${title}</h3><div class="deck-meta">${icon('cards')} ${d.cards.length} terms ${d.folder?`· ${esc(d.folder)}`:''}</div></div>
   <div class="row space-between small"><span class="muted">Mastery</span><strong>${p}%</strong></div><div class="bar"><span style="width:${p}%"></span></div>
   <div class="mini-metrics"><span>${m.accuracy===null?'—':m.accuracy+'%'} accuracy</span><span>${m.learning} learning</span><span>${m.unseen} new</span></div></article>`;
}

function deckInsights(d){const m=setMetrics(d),mistakes=recentMistakes(d),learning=learningCards(d).slice().sort((a,b)=>mastery(a)-mastery(b));return `<section class="surface" style="margin-top:19px"><h3>Set statistics</h3><div class="insight-grid"><div><strong>${m.accuracy===null?'—':m.accuracy+'%'}</strong><small>Accuracy</small></div><div><strong>${m.mastered}</strong><small>Mastered</small></div><div><strong>${m.learning}</strong><small>Learning</small></div><div><strong>${m.unseen}</strong><small>Not studied</small></div></div><div class="row wrap" style="margin-top:16px"><button class="btn small" data-act="start" data-mode="learn" data-scope="learning">Study learning</button><button class="btn small" data-act="start" data-mode="mc" data-scope="mistakes">Review last 10 mistakes</button></div><h3 style="margin-top:22px">Still learning</h3><div class="learning-scroll">${learning.length?learning.map(c=>`<div class="insight-term"><span>${esc(shortTerms(c.term,32))}</span><span class="pill">${mastery(c)}%</span></div>`).join(''):'<p class="muted small">No cards in progress yet. Start a quiz to build this list.</p>'}</div><h3 style="margin-top:22px">Last 10 mistakes</h3>${mistakes.length?mistakes.map(x=>`<div class="insight-term"><span>${esc(shortTerms(getCard(x.cardId,d)?.term||x.term,29))}</span><span class="muted small">${fmtDate(x.at)}</span></div>`).join(''):'<p class="muted small">Mistakes you make from now on appear here.</p>'}</section>`}
function logMistake(card){let deckId=ui.session?.deckId||ui.test?.deckId||ui.arcade?.deckId||ui.deckId;data.mistakeLog=Array.isArray(data.mistakeLog)?data.mistakeLog:[];data.mistakeLog.push({deckId,cardId:card.id,term:card.term,at:Date.now(),mode:ui.session?.mode||ui.arcade?.mode||'test'});if(data.mistakeLog.length>500)data.mistakeLog.splice(0,data.mistakeLog.length-500)}
function updatePractice(card,correct){if(correct){card.correct=(card.correct||0)+1;card.streak=(card.streak||0)+1}else{card.wrong=(card.wrong||0)+1;card.streak=0;logMistake(card)}card.lastReviewed=Date.now();save()}
function startMode(mode,scope='all'){
 clearInterval(timerHandle);timerHandle=null;ui.arcade=null;
 if(mode==='listen'&&!data.settings.showPronunciation){toast('Turn on optional pronunciation in Settings (Alt+P).');return}
  if(mode==='stroke'){const d=getDeck();if(!d||!hasHanziDeck(d)){toast('Chinese writing appears only for sets containing Chinese characters.');return;}ui.stroke={deckId:d.id,index:0,step:0,drawingCount:0,guide:true};ui.page='stroke';render();return;}
 const d=getDeck();if(!d?.cards?.length){toast('Add at least one card first.');return}
 if(mode==='test'){ui.page='test';ui.test={deckId:d.id,count:Math.min(20,d.cards.length),types:['mc','write','tf'],questions:[],submitted:false,result:null,started:Date.now()};render();return}
 if(mode==='match'){ui.page='match';initMatch();return}
 if(['blocks','charms','blast'].includes(mode)){startArcade(mode,d);return}
 let cards=mode==='review'?d.cards.filter(due):d.cards.slice();
 if(mode==='review'&&!cards.length){toast('Nothing due; practising your whole set instead.');cards=d.cards.slice()}
 if(scope==='learning')cards=learningCards(d);
 if(scope==='starred')cards=d.cards.filter(c=>c.starred);
 if(scope==='mistakes'){const ids=recentMistakes(d).map(m=>m.cardId);cards=ids.map(id=>getCard(id,d)).filter(Boolean)}
 if(!cards.length){toast(scope==='mistakes'?'No mistakes recorded yet.':scope==='starred'?'Star some cards first.':scope==='learning'?'No cards are marked as still learning yet.':'No cards to study.');return}
 if(mode==='blitz'&&d.cards.length<2){toast('Blitz needs at least two cards.');return}
 let ids=shuffle(cards.map(c=>c.id));ui.session={mode,scope,deckId:d.id,ids,pos:0,right:0,wrong:0,attempts:{},start:Date.now(),flip:false,feedback:null,phase:'question',q:null,starOnly:false,blitzLeft:60,completed:0};ui.page='study';
 if(['learn','mc','write','listen','blitz'].includes(mode))makeQuestion();
 if(mode==='blitz'){timerHandle=setInterval(()=>{if(!ui.session||ui.session.mode!=='blitz'){clearInterval(timerHandle);return}ui.session.blitzLeft--;if(ui.session.blitzLeft<=0){finishSession();return}let t=$('#blitz-clock');if(t)t.textContent=ui.session.blitzLeft+'s'},1000)}
 render();maybeAutoSpeak();
}
function modeTitle(m){return ({flash:'Flashcards',learn:'Learn',mc:'Multiple choice',write:'Written practice',test:'Practice test',match:'Match',review:'Spaced review',listen:'Listen & type',blitz:'Blitz',blocks:'Blocks',charms:'Charms',blast:'Blast'})[m]||m}
function shuffleSession(){let s=ui.session;if(!s||!['flash','review'].includes(s.mode))return;s.ids=shuffle(s.ids);s.pos=0;s.flip=false;render();toast('Cards reshuffled.')}
function flashView(s,c){let flip=s.flip;return `<div class="study-card" data-act="flip" role="button" tabindex="0" aria-label="Flip flashcard"><button class="icon-btn in-card-star ${c.starred?'active':''}" data-act="star" data-id="${c.id}" aria-label="${c.starred?'Unstar':'Star'} this flashcard" title="Star card (F)">${icon('star')}</button><span class="face-label">${flip?'BACK · DEFINITION':'FRONT · TERM'}</span><div class="study-word">${esc(flip?solutionText(c):promptText(c))}</div>${data.settings.showPronunciation&&!flip&&data.settings.direction==='forward'&&c.pinyin?`<div class="study-secondary">${esc(c.pinyin)}</div>`:''}${flip&&c.notes?`<div class="muted">${esc(c.notes)}</div>`:''}${c.image&&!flip?`<img alt="Card illustration" src="${safeImage(c.image)}" style="max-height:140px;border-radius:11px"/>`:''}${data.settings.showPronunciation?`<button class="icon-btn speak-float" data-act="speak" data-id="${c.id}" aria-label="Speak term">${icon('speaker')}</button>`:''}<div class="flip-note">Tap to flip <span class="kbd">Space</span></div></div><div class="study-controls"><button class="icon-btn" data-act="prev" ${s.pos===0?'disabled':''} aria-label="Previous card">${icon('back')}</button><button class="btn" data-act="flip">${icon('refresh')} Flip</button><button class="icon-btn" data-act="shuffle-session" aria-label="Shuffle flashcards" title="Shuffle (R)">${icon('shuffle')}</button><button class="icon-btn" data-act="next" aria-label="Next card">${icon('arrow')}</button></div>${s.mode==='review'?(s.flip?`<div class="surface" style="margin-top:21px;text-align:center"><p class="muted">How well did you remember this?</p><div class="row wrap" style="justify-content:center"><button class="btn danger" data-act="grade" data-grade="0">Again</button><button class="btn" data-act="grade" data-grade="1">Hard</button><button class="btn soft" data-act="grade" data-grade="2">Good</button><button class="btn primary" data-act="grade" data-grade="3">Easy</button></div></div>`:`<p class="center muted small" style="margin-top:20px">Flip to rate your memory.</p>`):`<p class="center muted small" style="margin-top:22px">← → Navigate · F star · R shuffle ${data.settings.showPronunciation?'· S speak':''}</p>`}`}
function finishArcade(){clearInterval(timerHandle);timerHandle=null;let g=ui.arcade;if(!g||g.finished)return;g.finished=true;data.history.push({deckId:g.deckId,mode:g.mode,correct:g.right,total:g.right+g.wrong,at:Date.now(),duration:Date.now()-g.started});data.arcadeBest=data.arcadeBest||{};let key=g.deckId+':'+g.mode;data.arcadeBest[key]=Math.max(data.arcadeBest[key]||0,g.score);save();render()}
function startArcade(mode,d){const cards=shuffle(d.cards);if(cards.length<2){toast('Games need at least two cards.');return}const len=Math.min(cards.length,mode==='blocks'?12:10);ui.arcade={mode,deckId:d.id,ids:cards.slice(0,len).map(c=>c.id),started:Date.now(),right:0,wrong:0,score:0,finished:false,hearts:mode==='blocks'?0:3,pos:0,selected:null,solved:[],cursor:Math.min(4,len),visible:cards.slice(0,Math.min(4,len)).map(c=>c.id),tickEnd:Date.now()+10000};ui.page='arcade';if(mode==='blocks'){let g=ui.arcade;g.blockTiles=shuffle(g.visible.flatMap(id=>[{id,side:'term',text:getCard(id,d)?.term},{id,side:'definition',text:getCard(id,d)?.definition}]))}if(mode==='blast'){timerHandle=setInterval(()=>{const g=ui.arcade;if(!g||g.mode!=='blast'||g.finished){clearInterval(timerHandle);return}if(Date.now()>=g.tickEnd)blastMiss();else{let bar=$('#blast-timer');if(bar)bar.style.width=Math.max(0,(g.tickEnd-Date.now())/100)+'%'}},100)}render()}
function arcadePage(){let g=ui.arcade;if(!g)return deckPage();let d=getDeck(g.deckId),best=(data.arcadeBest||{})[g.deckId+':'+g.mode]||0;if(g.finished)return `<div class="study-layout"><div class="arcade-finish"><div style="font-size:62px">${g.right? '🏆':'💪'}</div><div class="eyebrow">${esc(g.mode.toUpperCase())} COMPLETE</div><h1>${g.mode==='blast'&&g.hearts===0?'Mission ended':'Well played!'}</h1><div class="result-score">${g.score}</div><p>Points · ${g.right} correct · ${g.wrong} missed · Best ${best}</p><div class="row wrap" style="justify-content:center"><button class="btn primary" data-act="start" data-mode="${g.mode}">Play again</button><button class="btn" data-act="open-deck" data-id="${g.deckId}">Back to set</button></div></div></div>`;
 let top=`<div class="crumb"><button data-act="open-deck" data-id="${g.deckId}">${esc(d.title)}</button>${icon('arrow')} ${esc(modeTitle(g.mode))}</div><div class="arcade-heading"><div><div class="eyebrow">OFFLINE STUDY GAME</div><h1>${esc(modeTitle(g.mode))}</h1></div><div class="arcade-badges"><span class="pill">⭐ ${g.score}</span><span class="pill">${g.right}/${g.ids.length} cleared</span>${g.mode!=='blocks'?`<span class="pill">❤️ ${g.hearts}</span>`:''}</div></div>`;
 if(g.mode==='blocks'){let unsolved=g.visible.filter(id=>!g.solved.includes(id));let tiles=g.blockTiles.filter(t=>!g.solved.includes(t.id));return `<div class="study-layout arcade-layout">${top}<div class="surface"><p class="muted">Select a term and its matching definition. Each correct pair reveals the next blocks.</p><div class="blocks-grid">${tiles.map(t=>`<button class="block-tile ${g.selected?.id===t.id&&g.selected.side===t.side?'selected':''}" data-act="blocks-tile" data-id="${t.id}" data-side="${t.side}">${esc(t.text)}</button>`).join('')}</div><div class="row space-between small muted"><span>${g.wrong} mismatches</span><span>${g.solved.length}/${g.ids.length} cleared</span></div></div></div>`}
 let c=getCard(g.ids[g.pos],d),question=promptText(c),opts=arcadeChoices(c,d);if(g.mode==='charms')return `<div class="study-layout arcade-layout">${top}<div class="surface"><p class="muted">Find the meaning to earn a charm. Three hearts — keep your streak alive!</p><div class="charm-progress">${Array.from({length:g.ids.length},(_,i)=>`<span class="charm-pebble ${i<g.pos?'collected':i===g.pos?'current':''}">${i<g.pos?'✦':'◇'}</span>`).join('')}</div><div class="arcade-prompt">${esc(question)}</div><div class="arcade-options">${opts.map((v,i)=>`<button class="charm-option" data-act="charms-answer" data-choice="${i}"><span class="charm-shape">✦</span>${esc(v)}</button>`).join('')}</div></div></div>`;
 return `<div class="study-layout arcade-layout">${top}<div class="blast-sky"><div class="blast-stars" aria-hidden="true">✧ ✦ ⋆ ✧ ✦ ⋆</div><p>Blast the matching answer before it reaches your ship!</p><div class="blast-question">${esc(question)}</div><div class="blast-meter"><span id="blast-timer" style="width:${Math.max(0,(g.tickEnd-Date.now())/100)}%"></span></div><div class="blast-options">${opts.map((v,i)=>`<button class="meteor" data-act="blast-answer" data-choice="${i}"><span>☄</span>${esc(v)}</button>`).join('')}</div><div class="blast-ship" aria-hidden="true">🚀</div></div></div>`}
function arcadeChoices(c,d){let right=solutionText(c),others=shuffle([...new Set(d.cards.filter(x=>x.id!==c.id).map(solutionText).filter(x=>x!==right))]);let g=ui.arcade;if(!g.choices||g.questionId!==c.id){g.choices=shuffle([right,...others.slice(0,3)]);g.questionId=c.id}return g.choices}
function pickBlock(id,side){let g=ui.arcade;if(!g||g.mode!=='blocks'||g.finished)return;if(!g.selected){g.selected={id,side};render();return}let prev=g.selected;g.selected=null;if(prev.side===side){g.selected={id,side};render();return}if(prev.id!==id){g.wrong++;updatePractice(getCard(prev.id,getDeck(g.deckId)),false);cue(false);render();return}g.right++;g.score+=100;g.solved.push(id);updatePractice(getCard(id,getDeck(g.deckId)),true);cue(true);g.visible=g.visible.filter(x=>x!==id);g.blockTiles=g.blockTiles.filter(t=>t.id!==id);if(g.cursor<g.ids.length){let next=g.ids[g.cursor++];g.visible.push(next);let card=getCard(next,getDeck(g.deckId));g.blockTiles.push({id:next,side:'term',text:card.term},{id:next,side:'definition',text:card.definition});}if(g.solved.length>=g.ids.length){finishArcade();return}render()}
function answerCharm(index){let g=ui.arcade;if(!g||g.mode!=='charms'||g.finished)return;let c=getCard(g.ids[g.pos],getDeck(g.deckId));let ok=g.choices[index]===solutionText(c);g.right+=ok?1:0;g.wrong+=ok?0:1;g.score+=ok?100:0;g.hearts-=ok?0:1;updatePractice(c,ok);cue(ok);g.pos++;g.choices=null;if(g.pos>=g.ids.length||g.hearts<=0){finishArcade();return}render()}
function blastMiss(){let g=ui.arcade;if(!g||g.finished||g.mode!=='blast')return;let c=getCard(g.ids[g.pos],getDeck(g.deckId));g.wrong++;g.hearts--;updatePractice(c,false);cue(false);advanceBlast()}
function answerBlast(index){let g=ui.arcade;if(!g||g.finished||g.mode!=='blast')return;let c=getCard(g.ids[g.pos],getDeck(g.deckId));let ok=g.choices[index]===solutionText(c);g.right+=ok?1:0;g.wrong+=ok?0:1;g.score+=ok?120:0;g.hearts-=ok?0:1;updatePractice(c,ok);cue(ok);advanceBlast()}
function advanceBlast(){let g=ui.arcade;g.pos++;g.choices=null;g.tickEnd=Date.now()+10000;if(g.pos>=g.ids.length||g.hearts<=0){finishArcade();return}render()}
